import time, requests

def chamar(url, **kw):
    for _ in range(4):
        r = requests.request(**kw, url=url, timeout=60)
        if r.status_code == 429:
            time.sleep(int(r.headers.get('Retry-After', '5')) + 1)
            continue
        r.raise_for_status()
        return r.json()
    raise RuntimeError('limite de requisições: tentativas esgotadas')

import base64
from defusedxml import ElementTree as ET

def campo(xml_b64, tag):
    raiz = ET.fromstring(base64.b64decode(xml_b64))
    for el in raiz.iter():
        if el.tag.split('}')[-1] == tag:
            return el.text

